import {controller, target} from '@github/catalyst'
import {requestSubmit} from '@github-ui/form-utils'
import {debounce} from '@github/mini-throttle'

@controller
export class DependabotRunnerSettingsElement extends HTMLElement {
  static readonly VALID_INPUT_PATTERN = /^[a-zA-Z0-9._-]+$/
  static readonly DEFAULT_RUNNER_LABEL = 'dependabot'
  // Form and main components
  @target declare form: HTMLFormElement
  @target declare selectionStep: HTMLElement
  @target declare labeledFields: HTMLElement

  // Runner type selection
  @target declare runnerTypeSelect: HTMLElement
  @target declare runnerTypeHidden: HTMLInputElement

  // Input fields
  @target declare runnerGroupInput: HTMLInputElement
  @target declare runnerLabelInput: HTMLInputElement

  // Validation messages
  @target declare groupValidationMessage: HTMLElement
  @target declare groupValidationError: HTMLElement
  @target declare labelValidationMessage: HTMLElement
  @target declare labelValidationError: HTMLElement

  // Validation warnings
  @target declare groupValidationWarning: HTMLElement
  @target declare labelValidationWarning: HTMLElement

  // Lifecycle methods
  connectedCallback() {
    // Set initial state to saved state - this sets up ActionMenu properly
    this.resetToSavedState()

    // Set up dialog close event listeners
    this.setupDialogCloseListeners()

    // Set up validation listeners
    this.setupValidationListeners()

    // Ensure DOM updates after element is fully connected
    this.#scheduleInitialUpdate()
  }

  #scheduleInitialUpdate() {
    // Use requestAnimationFrame to ensure DOM is ready after current call stack
    requestAnimationFrame(() => {
      // Double-check that target elements are available before proceeding
      if (this.#areTargetElementsReady()) {
        this.updateFieldVisibility()
        this.updateGroupValidationWarning()
        this.updateLabelValidationWarning()
      } else {
        // If elements aren't ready yet, try again on next frame
        this.#scheduleInitialUpdate()
      }
    })
  }

  #areTargetElementsReady(): boolean {
    // Check if critical target elements are available
    return !!(this.labeledFields && this.groupValidationWarning && this.labelValidationWarning)
  }

  // Dialog and state management
  setupDialogCloseListeners() {
    const dialogId = 'dependabot-runner-settings-dialog'
    const dialog = document.getElementById(dialogId)

    if (dialog) {
      // Use MutationObserver to detect when dialog opens
      const observer = new MutationObserver(mutations => {
        for (const mutation of mutations) {
          if (mutation.type === 'attributes' && mutation.attributeName === 'open') {
            const dialogTarget = mutation.target as HTMLDialogElement
            if (dialogTarget.hasAttribute('open')) {
              // Small delay to ensure content is rendered
              setTimeout(() => this.resetToSavedState(), 10)
            }
          }
        }
      })

      observer.observe(dialog, {attributes: true, attributeFilter: ['open']})

      // Reset state when dialog is closed or cancelled
      dialog.addEventListener('close', () => this.resetToSavedState())
      dialog.addEventListener('cancel', () => this.resetToSavedState())
    }
  }

  handleDialogOpening() {
    // Reset state when the pencil button is clicked (before dialog opens)
    this.resetToSavedState()
  }

  resetToSavedState() {
    // Read initial values from data attributes
    const savedType = this.getSavedRunnerType()
    const savedGroup = this.getAttribute('data-runner-group') || ''
    const savedLabel = this.getAttribute('data-runner-label') || ''

    // Reset input values
    if (this.runnerGroupInput) {
      this.runnerGroupInput.value = savedGroup
    }
    if (this.runnerLabelInput) {
      // savedLabel will be empty for default case, so just set it directly
      this.runnerLabelInput.value = savedLabel
    }

    // Clear validation errors
    this.clearValidationErrors()

    // Update validation warnings
    this.updateGroupValidationWarning()
    this.updateLabelValidationWarning()

    // Reset internal state - IMPORTANT: This clears any temporary selection
    this.removeAttribute('data-selected-type')

    // Reset ActionMenu visual state to saved state
    this.updateActionMenuState(savedType)

    // Update field visibility based on saved state
    this.updateFieldVisibility()
  }

  updateActionMenuState(activeType: string | null) {
    // Look for buttons with role="menuitemradio" instead of li elements
    const menuItems = this.querySelectorAll('button[role="menuitemradio"]')

    for (const button of Array.from(menuItems)) {
      const itemValue = button.getAttribute('data-value')
      const isActive = itemValue === activeType

      // Update aria-checked for accessibility
      button.setAttribute('aria-checked', isActive.toString())
    }

    // Update the ActionMenu button text to match the selected option
    if (this.runnerTypeSelect && activeType) {
      const activeButton = Array.from(menuItems).find(button => {
        return button.getAttribute('data-value') === activeType
      })

      if (activeButton) {
        // Find the label text within the button
        const labelSpan = activeButton.querySelector('.ActionListItem-label')
        const buttonText = labelSpan?.textContent?.trim()

        if (buttonText) {
          // Find the specific span that contains the text we need to update
          const buttonLabelSpan = this.runnerTypeSelect.querySelector('.Button-label span:last-child')
          if (buttonLabelSpan) {
            buttonLabelSpan.textContent = buttonText
          } else {
            // Fallback: update the whole button text
            this.runnerTypeSelect.textContent = buttonText
          }
        }
      }
    }
  }

  // Runner type selection methods
  selectStandardGithubRunner() {
    this.setAttribute('data-selected-type', 'standard')
    this.updateActionMenuState('standard')
    this.updateFieldVisibility()
  }

  selectLabeledRunner() {
    this.setAttribute('data-selected-type', 'labeled')
    this.updateActionMenuState('labeled')
    this.updateFieldVisibility()
  }

  // Utility methods
  protected getSavedRunnerType(): string {
    return this.getAttribute('data-runner-type') || ''
  }

  updateFieldVisibility() {
    const selectedType = this.getAttribute('data-selected-type')
    const activeType = selectedType || this.getSavedRunnerType()

    if (this.labeledFields) {
      const shouldShow = activeType === 'labeled'
      this.labeledFields.style.display = shouldShow ? 'block' : 'none'
    }
  }

  resetDialog() {
    this.resetToSavedState()
  }

  // Form submission
  saveChanges() {
    const selectedType = this.getAttribute('data-selected-type')
    const finalType = selectedType || this.getSavedRunnerType()

    // Validate inputs before submission
    if (!this.validateInputs()) {
      return // Don't submit if validation fails
    }

    // Handle default label if field is empty
    if (this.runnerLabelInput && finalType === 'labeled') {
      const labelValue = this.runnerLabelInput.value.trim()
      if (!labelValue) {
        // Set default label if empty
        const defaultLabel =
          this.getAttribute('data-default-label') || DependabotRunnerSettingsElement.DEFAULT_RUNNER_LABEL
        this.runnerLabelInput.value = defaultLabel
      }
    }

    // Update hidden form field
    if (this.runnerTypeHidden && finalType) {
      this.runnerTypeHidden.value = finalType
    }

    // Submit the form
    if (this.form) {
      requestSubmit(this.form)
    }
  }

  // Validation methods
  setupValidationListeners() {
    // Create debounced validation handlers (300ms delay for input validation)
    const debouncedGroupValidation = debounce(() => {
      this.validateGroup()
      this.updateGroupValidationWarning()
    }, 300)

    const debouncedLabelValidation = debounce(() => {
      this.validateLabel()
      this.updateLabelValidationWarning()
    }, 300)

    // Add input validation listeners
    if (this.runnerGroupInput) {
      this.runnerGroupInput.addEventListener('input', debouncedGroupValidation)
      this.runnerGroupInput.addEventListener('blur', () => {
        this.validateGroup()
        this.updateGroupValidationWarning()
      })
    }

    if (this.runnerLabelInput) {
      this.runnerLabelInput.addEventListener('input', debouncedLabelValidation)
      this.runnerLabelInput.addEventListener('blur', () => {
        this.validateLabel()
        this.updateLabelValidationWarning()
      })
    }
  }

  validateInputs(): boolean {
    const selectedType = this.getAttribute('data-selected-type')
    const activeType = selectedType || this.getSavedRunnerType()

    // Only validate if labeled runner type is selected
    if (activeType !== 'labeled') {
      return true
    }

    const groupValid = this.validateGroup()
    const labelValid = this.validateLabel()

    return groupValid && labelValid
  }

  validateGroup(): boolean {
    if (!this.runnerGroupInput) return true
    return this.#validateInput(
      this.runnerGroupInput.value,
      'data-group-format-error',
      this.groupValidationMessage,
      this.groupValidationError,
    )
  }

  validateLabel(): boolean {
    if (!this.runnerLabelInput) return true
    return this.#validateInput(
      this.runnerLabelInput.value,
      'data-label-format-error',
      this.labelValidationMessage,
      this.labelValidationError,
    )
  }

  #validateInput(
    value: string,
    errorAttr: string,
    messageElement: HTMLElement | null,
    errorElement: HTMLElement | null,
  ): boolean {
    const errors: string[] = []

    // Format validation (letters, numbers, hyphens, underscores only)
    if (value && !DependabotRunnerSettingsElement.VALID_INPUT_PATTERN.test(value)) {
      const formatError = this.getAttribute(errorAttr)
      if (formatError) errors.push(formatError)
    }

    this.showValidationError(messageElement, errorElement, errors)
    return errors.length === 0
  }

  showValidationError(messageElement: HTMLElement | null, errorElement: HTMLElement | null, errors: string[]) {
    if (!messageElement || !errorElement) return

    if (errors.length > 0) {
      errorElement.textContent = errors[0] ?? '' // Show first error
      messageElement.hidden = false
    } else {
      messageElement.hidden = true
      errorElement.textContent = ''
    }
  }

  clearValidationErrors() {
    // Clear group validation errors
    if (this.groupValidationMessage) {
      this.groupValidationMessage.hidden = true
    }
    if (this.groupValidationError) {
      this.groupValidationError.textContent = ''
    }

    // Clear label validation errors
    if (this.labelValidationMessage) {
      this.labelValidationMessage.hidden = true
    }
    if (this.labelValidationError) {
      this.labelValidationError.textContent = ''
    }
  }

  // Validation warning methods
  updateGroupValidationWarning() {
    if (!this.groupValidationWarning || !this.runnerGroupInput) return

    const currentValue = this.runnerGroupInput.value.trim()
    // Only show warning if there's a value AND no validation errors showing
    const hasValidationErrors = this.groupValidationMessage && !this.groupValidationMessage.hidden
    const shouldShowWarning = currentValue.length > 0 && !hasValidationErrors

    if (shouldShowWarning) {
      this.groupValidationWarning.style.display = 'block'
    } else {
      this.groupValidationWarning.style.display = 'none'
    }
  }

  updateLabelValidationWarning() {
    if (!this.labelValidationWarning || !this.runnerLabelInput) return

    const currentValue = this.runnerLabelInput.value.trim()
    const defaultLabel = this.getAttribute('data-default-label') || DependabotRunnerSettingsElement.DEFAULT_RUNNER_LABEL
    // Only show warning if there's a custom value AND no validation errors showing
    const hasValidationErrors = this.labelValidationMessage && !this.labelValidationMessage.hidden
    const shouldShowWarning = currentValue.length > 0 && currentValue !== defaultLabel && !hasValidationErrors

    if (shouldShowWarning) {
      this.labelValidationWarning.style.display = 'block'
    } else {
      this.labelValidationWarning.style.display = 'none'
    }
  }
}
